head.script:
scwin.screenId = "jldinf90009";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 파라미터 수신(init_recvParam) 후 안내 문구 표시 조건을 평가(init_conds)한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신 (검색 조건/zipList 확보)
        scwin.init_conds(); // 2) 안내 문구(txt_p8) 표시 조건 평가
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf90009.onpageload' });
    }
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_conds
 * @description 검색 결과 목록(zipList)이 비어 있을 때만 안내 문구(txt_p8)를 표시하도록 조건을 평가한다(공용 $c.util.evalConds).
 * @returns {void}
 * @hidden N
 * @example scwin.init_conds();
 */
scwin.init_conds = function () {
    const binds = [{
        id: "txt_p8",
        fn: function () {
            const zipList = $c.data.readValue("dma_pageContext", "zipList", { ctx: true, label: "zipList" });
            return String(zipList == null ? '' : zipList).length === 0;
        }
    }];
    $c.util.evalConds(binds);
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name grd_zipList_oncellclick
 * @description 우편번호 목록 행 클릭 — 선택 행의 우편번호·주소·영문주소를 부모창으로 전달(setZipCode)하고 팝업을 닫는다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example (grd_zipList ev:oncellclick 바인딩으로 자동 호출)
 */
scwin.grd_zipList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_zipList');
        const r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.setZipCode(r["zipCode"], r["address"], r["engAddress"]);
        return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_zipList.oncellclick' });
    }
};


/**
 * @event
 * @name btn_sddSearchZip_onclick
 * @description [조회] 버튼 클릭 — 입력 검색어와 기존 검색 조건 컴포넌트 값을 모아 현재 프레임에서 자기 화면을 재조회한다.
 * @returns {void}
 * @hidden N
 * @example (btn_sddSearchZip ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_sddSearchZip_onclick = function () {
    try {
        const kw = ($c.util.getComponent('ibx_sddSearchKeyword') || { getValue: function () { return ''; } }).getValue().trim();
        const o = {};
        ['searchType', 'searchWord', 'searchBldgNo', 'searchBldgNm'].forEach(function (fd) {
            try {
                const c = $c.util.getComponent(fd);
                if (c && c.getValue) { o[fd] = c.getValue(); }
            } catch (e) {
                $c.exception.handleError(e, { notify: 'none', context: 'jldinf90009' });
            }
        });
        o.searchWord = kw;
        $c.win.setPageFrameSrc($c.win.getFrame(), '/jldinf90009/jldinf90009.xml', o);

    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf90009.btn_sddSearchZip_onclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name setZipCode
 * @description 선택한 우편번호·주소·영문주소를 부모창(opener)의 scwin.setZipCode 로 전달하고 팝업을 닫는다.
 * @param {String} zipCode 우편번호
 * @param {String} address 주소
 * @param {String} engAddress 영문 주소
 * @returns {void}
 * @hidden N
 * @example scwin.setZipCode("06000", "서울특별시 중구 …", "Jung-gu, Seoul …");
 */
scwin.setZipCode = function (zipCode, address, engAddress) {
    const openerScope = ($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function () { return null; }, scwin: {} };
    const openerScwin = openerScope.scwin || {};
    if (openerScwin !== scwin && typeof openerScwin.setZipCode === 'function') {
        openerScwin.setZipCode(zipCode, address, engAddress);
    }
    $c.win.closePopup([zipCode, address, engAddress]);
};
